insert into auslegungen (nr, code, frage, antwort, kategorie, quellen, verbindlichkeit, bezug_nr, flag, ausspielen) values
(1, 'A01', $q$Wir lassen unsere Marmelade bei einem Lohnabfüller abfüllen – der sagt jetzt, WIR seien der „Erzeuger“. Unter dem VerpackG war doch immer der Abfüller der Hersteller?$q$, $q$Einordnung: Die PPWR trennt zwei Rollen, die das VerpackG in „Hersteller“ bündelte. Erzeuger (Konformitätsschiene) ist, wer die Verpackung oder das verpackte Produkt unter eigenem Namen oder eigener Marke entwickeln oder herstellen LÄSST – das eigene Abfüllen ist nicht nötig (Art. 3 Abs. 1 Nr. 13 lit. a PPWR). Läuft die Marmelade unter Ihrer Marke, sind Sie der Erzeuger, nicht der Lohnabfüller. Folge: Sie verantworten Konformitätsbewertung (Art. 38), technische Dokumentation (Anhang VII) und EU-Konformitätserklärung (Art. 39) – auch wenn Dritte zuarbeiten (Art. 15 Abs. 2). Die davon getrennte EPR-Rolle „Hersteller“ (Registrierung, Systembeteiligung) ist gesondert zu prüfen (siehe A02). Quellen: Art. 3 Abs. 1 Nr. 13 lit. a, Art. 15 Abs. 1 u. 2, Art. 38, Art. 39 PPWR; Leitfaden C(2026) 3702, Abschn. 2 (unverbindliche Auslegung der EU-Kommission). Grenze: Ist Ihr Unternehmen ein Kleinstunternehmen, kann die Erzeuger-Rolle auf den Verpackungslieferanten übergehen (Nr. 13 lit. b, siehe A04).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 lit. a PPWR$q$,$q$Art. 15 Abs. 1 u. 2 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 2$q$]::text[], 'rechtsverbindlich', '{8,4,6}'::int[], null, true),
(2, 'A02', $q$Und wer von uns beiden muss dann bei LUCID registriert sein und lizenzieren – wir als Markeninhaber oder unser Lohnabfüller?$q$, $q$Einordnung: Die EPR-Rolle „Hersteller“ trägt, wer das verpackte Produkt erstmals im Bundesgebiet bereitstellt (Art. 3 Abs. 1 Nr. 15 lit. b PPWR). „Bereitstellung“ ist jede entgeltliche oder unentgeltliche Abgabe zum Vertrieb, Verbrauch oder zur Verwendung (Nr. 11). Bei klassischer Lohnfertigung bleibt die Ware im Eigentum des Auftraggebers; die erste Abgabe in die Lieferkette erfolgt dann durch den Auftraggeber – nach dieser Lesart sind SIE der Hersteller und müssen registrieren (§ 6 VerpackDG) und sich an einem System beteiligen (§ 7). Verkauft der Abfüller die befüllte Ware dagegen an Sie, stellt ER erstmals bereit (vgl. A03). Folge: Vertragskonstellation prüfen (Eigentumsübergang, wer gibt an wen ab); Rollen-Check je Produktlinie. Quellen: Art. 3 Abs. 1 Nr. 11 u. 15 lit. b PPWR; §§ 6, 7 VerpackDG; Leitfaden Abschn. 3 (unverbindlich: „Hersteller ist regelmäßig der Abfüller, der erstmals bereitstellt“). Grenze: Die Zuordnung bei Lohnfertigung ohne Eigentumsübergang ist im Leitfaden nicht ausdrücklich behandelt – Auslegung, in der Cattwyk-Session zu bestätigen (!).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 11 PPWR$q$,$q$Art. 3 Abs. 1 Nr. 15 lit. b PPWR$q$,$q$§§ 6, 7 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$]::text[], 'unverbindliche_auslegung', '{8,31,32}'::int[], $q$! Lohnfertigungs-Zuordnung in Session bestätigen$q$, false),
(3, 'A03', $q$Wir produzieren Fertiggerichte als Eigenmarke für eine große Handelskette. Wer ist jetzt was – wir oder der Händler?$q$, $q$Einordnung: Beim mehrstufigen Private Label fallen die Rollen typischerweise auseinander. Erzeuger ist der Händler, weil das Produkt unter SEINER Marke hergestellt wird (Art. 3 Abs. 1 Nr. 13 lit. a PPWR) – er trägt die Konformitätsverantwortung (Art. 15). Hersteller (EPR) sind dagegen SIE, weil Sie das verpackte Produkt erstmals im Bundesgebiet bereitstellen, nämlich durch den Verkauf an den Händler (Nr. 15 lit. b). Folge: Der Händler braucht Konformitätsbewertung, technische Doku und Konformitätserklärung; Sie brauchen Registrierung (§ 6 VerpackDG), Systembeteiligung (§ 7) und Datenmeldung (§ 9). Unter dem VerpackG lag beides beim Erstinverkehrbringer – diese Bündelung gibt es nicht mehr. Quellen: Art. 3 Abs. 1 Nr. 13 lit. a u. Nr. 15 lit. b, Art. 15 PPWR; §§ 6, 7, 9 VerpackDG; Leitfaden Abschn. 2 u. 3 (unverbindliche Auslegung: Abfüller = regelmäßig Hersteller bei Verkaufsverpackungen). Grenze: Bei Kleinstunternehmen-Konstellationen und bei Direktbelieferung anderer Mitgliedstaaten verschieben sich die Rollen (A04, A16).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 lit. a PPWR$q$,$q$Art. 3 Abs. 1 Nr. 15 lit. b PPWR$q$,$q$§§ 6, 7, 9 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 2 u. 3$q$]::text[], 'rechtsverbindlich', '{8,31,32,33}'::int[], null, true),
(4, 'A04', $q$Wir sind ein kleiner Onlineshop (6 Leute) und lassen Kerzen mit unserem Logo produzieren. Stimmt es, dass wir uns um die ganze Konformitätsbürokratie NICHT kümmern müssen?$q$, $q$Einordnung: Ja, wenn die Kleinstunternehmen-Ausnahme greift: Fällt der Markeninhaber unter die am 11.02.2025 geltende Kleinstunternehmen-Definition der Empfehlung 2003/361/EG (unter 10 Beschäftigte UND Jahresumsatz oder Bilanzsumme max. 2 Mio. €) und sitzt der Verpackungslieferant im SELBEN Mitgliedstaat, gilt der Lieferant als Erzeuger (Art. 3 Abs. 1 Nr. 13 lit. b PPWR). Folge: Konformitätsbewertung, technische Doku und EU-Konformitätserklärung liegen dann beim Lieferanten – unabhängig davon, ob dieser selbst ein Kleinstunternehmen ist (Leitfaden Abschn. 2). Ihre EPR-Pflichten als Hersteller (Registrierung, Systembeteiligung) bleiben davon UNBERÜHRT. Quellen: Art. 3 Abs. 1 Nr. 13 lit. b PPWR; Empfehlung 2003/361/EG (Fassung 11.02.2025); Leitfaden C(2026) 3702 Abschn. 2 (unverbindliche Auslegung). Grenze: Verbundene Unternehmen werden mitgerechnet (A05); bezieht Ihr Lieferant aus einem anderen Mitgliedstaat oder Drittland, greift lit. b nicht (A06).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 lit. b PPWR$q$,$q$Empfehlung 2003/361/EG$q$,$q$Leitfaden C(2026) 3702 Abschn. 2$q$]::text[], 'rechtsverbindlich', '{8}'::int[], null, true),
(5, 'A05', $q$Wir sind ein Franchise-Betrieb mit 4 Mitarbeitern – zählen wir als Kleinstunternehmen, oder zählt da der ganze Franchise-Verbund?$q$, $q$Einordnung: Für die Kleinstunternehmen-Prüfung (Art. 3 Abs. 1 Nr. 13 lit. b, Art. 21 UAbs. 2 PPWR) sind verbundene und Partnerunternehmen nach Art. 3 des Anhangs der Empfehlung 2003/361/EG einzubeziehen. Der Leitfaden konkretisiert für Franchise: Ein Franchisenehmer kann Kleinstunternehmen sein, wenn der Franchisegeber nicht direkt oder indirekt 25 % oder mehr des Kapitals oder der Stimmrechte hält und keine Kontrolle oder keinen beherrschenden Einfluss ausübt; andernfalls sind die Daten des Franchisegebers hinzuzurechnen. Folge: Prüfen Sie den Franchisevertrag auf Beteiligungs- und Kontrollrechte; erst danach steht fest, ob die Erzeuger-Entlastung greift. Quellen: Art. 3 Abs. 1 Nr. 13 lit. b PPWR; Empfehlung 2003/361/EG, Anhang Art. 3; Leitfaden C(2026) 3702 Abschn. 2 (unverbindliche Auslegung der EU-Kommission). Grenze: Die Franchise-Aussage stammt allein aus dem Leitfaden und ist rechtlich nicht bindend; bei Kontroll-Zweifelsfällen Einzelfallberatung (Eskalation, vgl. U8 Rollen-Engine).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 lit. b PPWR$q$,$q$Empfehlung 2003/361/EG Anhang Art. 3$q$,$q$Leitfaden C(2026) 3702 Abschn. 2$q$]::text[], 'unverbindliche_auslegung', '{8}'::int[], $q$! U8: Verbund-/Franchise-Eskalationsschwelle$q$, false),
(6, 'A06', $q$Kleinstunternehmen wie wir sind doch befreit – unser Tütenlieferant sitzt allerdings in Polen. Ändert das was?$q$, $q$Einordnung: Ja, entscheidend. Die Kleinstunternehmen-Entlastung des Art. 3 Abs. 1 Nr. 13 lit. b PPWR setzt zwingend voraus, dass der Verpackungslieferant im SELBEN Mitgliedstaat ansässig ist wie Sie. Sitzt er in Polen und Sie in Deutschland, ist die Bedingung nicht erfüllt. Folge: Sie bleiben trotz Kleinstunternehmen-Status Erzeuger nach lit. a und tragen die volle Konformitätsverantwortung (Art. 15, 38, 39 PPWR). Es gibt auch keine allgemeine „Kleinunternehmer-Befreiung“ von den EPR-Pflichten: Registrierung und Systembeteiligung gelten größenunabhängig (§§ 6, 7 VerpackDG); lediglich Melde-Erleichterungen unter 10 Tonnen (§ 9 Abs. 2) und VE-Schwellen (§ 10 Abs. 4) knüpfen an Mengen an. Quellen: Art. 3 Abs. 1 Nr. 13 lit. a u. b PPWR; §§ 6, 7, 9 Abs. 2, 10 Abs. 4 VerpackDG. Grenze: Keine – der Wortlaut „im selben Mitgliedstaat“ ist eindeutig.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 lit. a u. b PPWR$q$,$q$§§ 6, 7 VerpackDG$q$,$q$§ 9 Abs. 2 VerpackDG$q$,$q$§ 10 Abs. 4 VerpackDG$q$]::text[], 'rechtsverbindlich', '{8,31,33}'::int[], null, true),
(7, 'A07', $q$Wir sind Großhändler und packen importierte Palettenware aus, um sie neu zu kommissionieren. Ein Berater meint, wir seien jetzt „Hersteller“ – wir stellen doch gar nichts her?!$q$, $q$Einordnung: Der Berater hat vermutlich recht. „Hersteller“ ist in der PPWR keine Produktionsrolle, sondern die EPR-Rolle. Nach dem Auffangtatbestand des Art. 3 Abs. 1 Nr. 15 lit. e PPWR ist Hersteller, wer in einem Mitgliedstaat niedergelassen ist und verpackte Produkte AUSPACKT, ohne Endabnehmer zu sein – es sei denn, eine andere Person ist bereits Hersteller nach lit. a–d. Bei Direktimporten gibt es vor Ihnen niemanden in der deutschen Lieferkette, also greift lit. e bei Ihnen. Folge: Registrierung bei der ZSVR bereits VOR dem Auspacken (§ 6 Abs. 1 VerpackDG), Systembeteiligung vor dem Auspacken (§ 7 Abs. 1), Datenmeldung (§ 9); ohne Registrierung gilt ein Auspack-Verbot (§ 13 Abs. 1). Quellen: Art. 3 Abs. 1 Nr. 15 lit. e PPWR; §§ 6 Abs. 1, 7 Abs. 1, 9, 13 Abs. 1 VerpackDG. Grenze: Verwenden Sie die ausgepackte Ware selbst (Endabnehmer), greift lit. e nicht (A08).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. e PPWR$q$,$q$§ 6 Abs. 1 VerpackDG$q$,$q$§ 7 Abs. 1 VerpackDG$q$,$q$§ 13 Abs. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{8,31,32}'::int[], null, true),
(8, 'A08', $q$Unser Betrieb packt angelieferte Kartons von deutschen Lieferanten aus und wirft die Verpackung weg. Müssen wir uns deshalb registrieren lassen?$q$, $q$Einordnung: In dieser Konstellation regelmäßig nein, aus zwei Gründen. Erstens ist der Auspacker-Tatbestand subsidiär: Er greift nur, wenn NICHT bereits eine andere Person Hersteller nach Art. 3 Abs. 1 Nr. 15 lit. a–d PPWR ist. Bei Ware von deutschen Lieferanten hat deren erste Bereitstellung im Bundesgebiet die Herstellerrolle bereits beim Lieferanten (oder davor) begründet. Zweitens sind Sie, wenn Sie das Produkt selbst verwenden und nicht in der gelieferten Form weitervertreiben, Endabnehmer (Nr. 23) – und der Auspacker-Tatbestand setzt gerade voraus, dass man KEIN Endabnehmer ist. Folge: Keine Registrierungspflicht aus dem Auspacken; als gewerblicher Endabnehmer können Sie für B2B-Verpackungen die unentgeltliche Rücknahme durch Hersteller/Vertreiber verlangen (§ 39 Abs. 1 VerpackDG). Quellen: Art. 3 Abs. 1 Nr. 15 lit. e u. Nr. 23 PPWR; § 39 Abs. 1 VerpackDG. Grenze: Anders bei Direktbezug aus dem Ausland ohne vorherigen deutschen Hersteller (A07) oder wenn Sie umverpackt weiterversenden (A09).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. e PPWR$q$,$q$Art. 3 Abs. 1 Nr. 23 PPWR$q$,$q$§ 39 Abs. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{8,34}'::int[], null, true),
(9, 'A09', $q$Wir sind Fulfillment-Dienstleister und packen für einen US-Kunden Container-Ware in kleinere Sendungen um. Die Ware gehört uns nie – kann uns das Verpackungsrecht trotzdem treffen?$q$, $q$Einordnung: Ja, doppelt. Erstens gelten für Sie als Fulfilment-Dienstleister (Definition über Art. 3 Abs. 1 UAbs. 3 PPWR i. V. m. Art. 3 Nr. 11 VO (EU) 2019/1020: mindestens zwei Leistungen aus Lagerhaltung, Verpackung, Adressierung, Versand ohne Eigentum) die Pflichten des Art. 20 PPWR sowie § 13 Abs. 4 VerpackDG: Sie dürfen für nicht ordnungsgemäß registrierte Hersteller nicht tätig werden; die ZSVR stellt dafür einen automatisierten Datenabgleich bereit. Zweitens werden Sie beim Umpacken importierter Drittlandsware nach der Kommissions-Auslegung selbst Hersteller der Transportverpackung nach Art. 3 Abs. 1 Nr. 15 lit. e – ausdrücklich AUCH ohne Eigentum an der Ware; Logistiker, die importierte Ware auspacken oder umpacken, sind keine Endabnehmer (Leitfaden Abschn. 3, letzter Absatz). Folge: eigene Registrierung vor dem Auspacken (§ 6 Abs. 1), Systembeteiligung soweit systembeteiligungspflichtig, plus Kunden-Screening gegen LUCID. Quellen: Art. 3 Abs. 1 UAbs. 3, Art. 3 Abs. 1 Nr. 15 lit. e, Art. 20, Art. 45 Abs. 7 PPWR; § 13 Abs. 4, § 6 Abs. 1 VerpackDG; Leitfaden Abschn. 3 (unverbindliche Auslegung). Grenze: Der genaue Definitionswortlaut der VO 2019/1020 liegt nicht in den Projektquellen (U5) – Wortlaut-Pin in der Session.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. e PPWR$q$,$q$Art. 20 PPWR$q$,$q$§ 13 Abs. 4 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$]::text[], 'unverbindliche_auslegung', '{39,8,31}'::int[], $q$! U5: Wortlaut VO 2019/1020 pinnen$q$, false),
(10, 'A10', $q$Unser US-Mutterkonzern hat in Deutschland nur eine Zweigniederlassung mit Umsatzsteuernummer. Reicht die, um als Importeur aufzutreten und die Registrierung zu machen?$q$, $q$Einordnung: Nein. Importeur kann nur eine IN DER UNION ANSÄSSIGE natürliche oder juristische Person sein (Art. 3 Abs. 1 Nr. 17 PPWR). Nach der Kommissions-Auslegung erfüllt eine unselbstständige Zweigniederlassung dieses Merkmal nicht: Sie hat keine eigene Rechtspersönlichkeit, handelt nur unter der Identität der Muttergesellschaft und kann daher weder Importeur noch Vertreiber im Sinne der PPWR sein; eine bloße Umsatzsteuer-Registrierung oder steuerliche Betriebsstätte genügt ausdrücklich nicht (Leitfaden Abschn. 4, mit EuGH-Nachweisen). Folge: Der Konzern braucht entweder eine EU-Tochtergesellschaft mit eigener Rechtspersönlichkeit oder – für die EPR-Schiene bei Direktvertrieb – einen Bevollmächtigten für die erweiterte Herstellerverantwortung (§ 5 Abs. 2 VerpackDG); für die Konformitätsschiene kann der Erzeuger einen Bevollmächtigten nach Art. 17 mandatieren. Quellen: Art. 3 Abs. 1 Nr. 17 u. 19 PPWR; Art. 17 PPWR; § 5 Abs. 2 VerpackDG; Leitfaden C(2026) 3702 Abschn. 4 (unverbindliche Auslegung, gestützt auf Blue Guide und EuGH). Grenze: Die Niederlassungs-Auslegung selbst ist Leitfaden-basiert; das Ergebnis folgt aber bereits aus dem Wortlaut „ansässige … Person“.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 17 PPWR$q$,$q$Art. 17 PPWR$q$,$q$§ 5 Abs. 2 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 4$q$]::text[], 'rechtsverbindlich', '{37,9}'::int[], null, true),
(11, 'A11', $q$Was ist der Unterschied zwischen dem „Bevollmächtigten“ und dem „Bevollmächtigten für die erweiterte Herstellerverantwortung“? Brauchen wir beide?$q$, $q$Einordnung: Das sind zwei völlig getrennte Institute auf zwei Schienen. Der Bevollmächtigte nach Art. 3 Abs. 1 Nr. 19 i. V. m. Art. 17 PPWR wird vom ERZEUGER schriftlich mandatiert und übernimmt Aufgaben der Konformitätsschiene (z. B. Ausstellung der EU-Konformitätserklärung) – er ist stets freiwillig. Der Bevollmächtigte für die erweiterte Herstellerverantwortung nach Nr. 20 i. V. m. Art. 45 Abs. 3 wird vom HERSTELLER benannt und übernimmt die EPR-Pflichten im Zielstaat – er ist in den Fällen des Art. 45 Abs. 3 PFLICHT (grenzüberschreitender Direktvertrieb an Endabnehmer; in Deutschland zusätzlich Drittlands-Hersteller ohne Niederlassung, § 5 Abs. 2 VerpackDG). Folge: Je nach Konstellation brauchen Sie keinen, einen oder beide; die Mandate sind getrennt zu dokumentieren. In Deutschland gilt: nur EIN EHV-Bevollmächtigter je Hersteller, schriftliche Vollmacht in deutscher Sprache, Benennung gegenüber der ZSVR; die Registrierung selbst ist nicht delegierbar (§ 5 Abs. 1 Satz 2, Abs. 4, Abs. 5 VerpackDG). Quellen: Art. 3 Abs. 1 Nr. 19 u. 20, Art. 17, Art. 45 Abs. 3 PPWR; § 5 VerpackDG. Grenze: Keine.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 19 u. 20 PPWR$q$,$q$Art. 17 PPWR$q$,$q$Art. 45 Abs. 3 PPWR$q$,$q$§ 5 VerpackDG$q$]::text[], 'rechtsverbindlich', '{9,6}'::int[], null, true),
(12, 'A12', $q$Wir sitzen in Österreich und verkaufen über unseren Webshop direkt an deutsche Endkunden. Was müssen wir in Deutschland tun?$q$, $q$Einordnung: Sie sind Hersteller in Deutschland nach Art. 3 Abs. 1 Nr. 15 lit. d PPWR (Erstbereitstellung verpackter Produkte direkt an Endabnehmer im Hoheitsgebiet eines anderen Mitgliedstaats); beim Online-Verkauf gilt bereits das Angebot an den Endkunden als Bereitstellung im Zielstaat (Leitfaden Abschn. 3). Folge: Vor der ersten Bereitstellung müssen Sie (1) einen Bevollmächtigten für die erweiterte Herstellerverantwortung mit schriftlicher Vollmacht in deutscher Sprache beauftragen (Art. 45 Abs. 3 Satz 1 PPWR; § 5 Abs. 2 Satz 1, Abs. 4 VerpackDG), (2) sich selbst bei der ZSVR registrieren – die Registrierung ist NICHT delegierbar (§ 5 Abs. 1 Satz 2, § 6 Abs. 1), wobei der Bevollmächtigte mitzubenennen ist (§ 6 Abs. 2 Nr. 2), und (3) die Systembeteiligung sicherstellen, die der Bevollmächtigte im eigenen Namen wahrnimmt (§ 5 Abs. 3, § 7). Ohne Registrierung/Beteiligung: Vertriebsverbot (§ 13). Quellen: Art. 3 Abs. 1 Nr. 15 lit. d, Art. 45 Abs. 3 PPWR; §§ 5, 6, 7, 13 VerpackDG; Leitfaden Abschn. 3 (Online-Angebot, unverbindliche Auslegung). Grenze: Mit eigener Niederlassung in Deutschland entfällt die Bevollmächtigten-Pflicht (§ 5 Abs. 2: „keine Niederlassung im Bundesgebiet“).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. d PPWR$q$,$q$Art. 45 Abs. 3 Satz 1 PPWR$q$,$q$§ 5 Abs. 2–5 VerpackDG$q$,$q$§ 6 VerpackDG$q$,$q$§ 13 VerpackDG$q$]::text[], 'rechtsverbindlich', '{9,31,32}'::int[], null, true),
(13, 'A13', $q$Unser Lieferant sitzt in China und verkauft parallel über einen Online-Marktplatz direkt an deutsche Verbraucher. Kann der überhaupt deutscher „Hersteller“ sein – und wer haftet, wenn er sich nicht registriert?$q$, $q$Einordnung: Ja. Auch ein in einem Drittland niedergelassener Anbieter ist Hersteller in Deutschland, wenn er verpackte Produkte erstmals direkt an Endabnehmer im Bundesgebiet bereitstellt (Art. 3 Abs. 1 Nr. 15 lit. d PPWR: „in einem Mitgliedstaat oder in einem Drittland niedergelassen“). Deutschland hat die Option des Art. 45 Abs. 3 Satz 2 PPWR ausgeübt: Solche Drittlands-Hersteller ohne Niederlassung im Bundesgebiet müssen vor der ersten Bereitstellung einen EHV-Bevollmächtigten benennen und beauftragen (§ 5 Abs. 2 Satz 2 VerpackDG). Folge für die Kette: Online-Plattformen müssen vor Freischaltung Registrierungsnachweis und Selbstbescheinigung des Herstellers einholen (Art. 45 Abs. 4 PPWR); Fulfilment-Dienstleister dürfen für nicht registrierte Hersteller nicht tätig werden (§ 13 Abs. 4 VerpackDG); Vertreiber dürfen deren Verpackungen nicht bereitstellen (§ 13 Abs. 3). Die Registrierungspflicht selbst bleibt beim Hersteller und ist nicht delegierbar (§ 5 Abs. 1 Satz 2). Quellen: Art. 3 Abs. 1 Nr. 15 lit. d, Art. 45 Abs. 3 Satz 2 u. Abs. 4 PPWR; § 5 Abs. 2 Satz 2, § 13 Abs. 3 u. 4 VerpackDG. Grenze: Zivilrechtliche Haftungsfragen zwischen Ihnen und dem Lieferanten sind Einzelfallberatung.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. d PPWR$q$,$q$Art. 45 Abs. 3 Satz 2 u. Abs. 4 PPWR$q$,$q$§ 5 Abs. 2 Satz 2 VerpackDG$q$,$q$§ 13 Abs. 3 u. 4 VerpackDG$q$]::text[], 'rechtsverbindlich', '{9,39,38}'::int[], null, true)
on conflict (nr) do nothing;insert into auslegungen (nr, code, frage, antwort, kategorie, quellen, verbindlichkeit, bezug_nr, flag, ausspielen) values
(14, 'A14', $q$Ich betreibe eine Bäckerei und kaufe meine Brötchentüten beim deutschen Großhandel. Muss ich die Tüten wie früher selbst lizenzieren – oder kann ich das wieder „nach oben“ abgeben?$q$, $q$Einordnung: Die Systematik hat sich zu Ihren Gunsten gedreht. Serviceverpackungen gehören zu den Verpackungsarten, bei denen die Herstellerrolle an der LEEREN Verpackung ansetzt: Hersteller ist, wer die Transport-, Service- oder Primärproduktionsverpackung erstmals im Bundesgebiet bereitstellt (Art. 3 Abs. 1 Nr. 15 lit. a PPWR) – also Ihr Großhändler bzw. der Tütenproduzent, nicht Sie als Befüller. Genau diese Entlastung kleiner Befüller ist ausdrückliches Regelungsziel (ErwG 122 PPWR). Folge: Beim Inlandsbezug bereits systembeteiligter Serviceverpackungen müssen Sie regelmäßig weder registrieren noch lizenzieren; lassen Sie sich die Systembeteiligung vom Lieferanten bestätigen. Das alte Modell „Übertragung auf den Vorvertreiber“ (§ 7 Abs. 2 VerpackG a. F.) existiert im VerpackDG nur noch für einen Sonderfall (A15). Quellen: Art. 3 Abs. 1 Nr. 15 lit. a, ErwG 122 PPWR; Leitfaden C(2026) 3702 Abschn. 3; § 3 Abs. 6 VerpackDG (Serviceverpackungen systembeteiligungspflichtig). Grenze: Anders bei Direktimport der leeren Tüten (dann sind Sie erster in der deutschen Kette) oder bei eigener Marke AUF der Tüte (A15).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. a PPWR$q$,$q$ErwG 122 PPWR$q$,$q$§ 3 Abs. 6 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$]::text[], 'rechtsverbindlich', '{8,32}'::int[], null, true),
(15, 'A15', $q$Unsere Imbisskette lässt Serviceverpackungen mit eigenem Logo bedrucken. Ein Kollege sagt, es gebe im neuen Gesetz noch eine Übertragungsmöglichkeit auf den Lieferanten – stimmt das?$q$, $q$Einordnung: Ja, aber eng zugeschnitten. § 7 Abs. 2 VerpackDG erlaubt die Übertragung der Systembeteiligungspflicht auf die Vorvertreiber der unbefüllten Serviceverpackungen – allerdings nur für den Hersteller, „der nach Artikel 21 der Verordnung (EU) 2025/40 als Erzeuger gilt“. Art. 21 erfasst Importeure/Vertreiber, die Verpackungen unter EIGENER Marke in Verkehr bringen oder konformitätsrelevant verändern. Mit Ihrem Logo-Druck können Sie in diese Konstellation fallen. Folge: Sie können vom Vorvertreiber verlangen, dass er sich hinsichtlich der gelieferten unbefüllten Serviceverpackungen am System beteiligt und Ihnen dies bestätigt; mit der Übertragung gehen die Pflichten aus §§ 6, 9, 10 insoweit über – Ihre EIGENE Registrierungspflicht bleibt aber bestehen, und bei vollständiger Übertragung geben Sie die Erklärung nach § 6 Abs. 2 Satz 3 ab („ausschließlich bereits systembeteiligte Serviceverpackungen“). Quellen: § 7 Abs. 2, § 6 Abs. 2 Satz 3 VerpackDG; Art. 21 PPWR. Grenze: Welcher Anwendungsbereich für die Übertragung im Vergleich zu § 7 Abs. 2 VerpackG a. F. praktisch verbleibt, ist offen (U2 Rollen-Engine) – Kernfrage der Cattwyk-Session; bis dahin keine Gestaltungsempfehlung im Produkt.$q$, 'rollen_epr', array[$q$§ 7 Abs. 2 VerpackDG$q$,$q$§ 6 Abs. 2 Satz 3 VerpackDG$q$,$q$Art. 21 PPWR$q$]::text[], 'unverbindliche_auslegung', '{32,8}'::int[], $q$! U2: Anwendungsbereich § 7 Abs. 2 in Session$q$, false),
(16, 'A16', $q$Wir füllen in Deutschland ab und verkaufen einen Teil der Ware an einen französischen Großhändler. Müssen wir für diese Mengen in Deutschland lizenzieren?$q$, $q$Einordnung: Nein. Die Herstellerrolle entsteht je Mitgliedstaat dort, wo die Verpackung erstmals bereitgestellt wird – im Staat, in dem sie voraussichtlich zu Abfall wird (Art. 3 Abs. 1 Nr. 15 lit. b, ErwG 122 PPWR). Liefern Sie an den französischen Großhändler, erfolgt die erste Bereitstellung in Frankreich; dort ist der Großhändler als erstes Glied der französischen Kette der Hersteller (Leitfaden Abschn. 3, Beispiel „Company D“). Für diese Mengen sind Sie in Deutschland nicht systembeteiligungspflichtig. Folge: Mengentrennung im Reporting (Inland vs. Ausland); für nachweislich nicht im Bundesgebiet an Endabnehmer abgegebene Verpackungen greift zudem die Ausnahme § 11 Nr. 4 VerpackDG. Prüfen Sie spiegelbildlich Ihre EPR-Pflichten in Frankreich (nationale Umsetzung). Quellen: Art. 3 Abs. 1 Nr. 15 lit. b, Nr. 11, ErwG 122 PPWR; § 11 Nr. 4 VerpackDG; Leitfaden C(2026) 3702 Abschn. 3 (unverbindliche Auslegung). Grenze: Beim Direktverkauf an END-abnehmer in Frankreich wären SIE dort Hersteller (lit. d) mit Bevollmächtigten-Pflicht (A12 spiegelbildlich).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. b PPWR$q$,$q$ErwG 122 PPWR$q$,$q$§ 11 Nr. 4 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$]::text[], 'rechtsverbindlich', '{8,32}'::int[], null, true),
(17, 'A17', $q$Wir haben Ware in Deutschland lizenziert, unser Kunde hat sie dann doch komplett nach Österreich weiterverkauft. Bekommen wir die Beteiligungsentgelte zurück?$q$, $q$Einordnung: Die PPWR-Systematik sieht das vor: Wird nach Gebührenzahlung in einem Mitgliedstaat die Verpackung durch einen Vertreiber erstmals im Hoheitsgebiet eines ANDEREN Mitgliedstaats bereitgestellt, sind die Entgelte zu erstatten („the fees must be reimbursed“, Leitfaden Abschn. 3 zu Art. 45 Abs. 1). Das VerpackDG regelt einen ausdrücklichen Erstattungsanspruch bislang nur für den Fall beschädigter/unverkäuflicher, nicht an Endabnehmer abgegebener Ware (§ 7 Abs. 3). Folge: Praktisch führt der Weg über das jeweilige System (vertragliche Export-Mengenkorrektur/Gutschrift) und über saubere Export-Nachweise; künftig vermeiden Sie die Doppelbelastung ex ante über § 11 Nr. 4 VerpackDG (nachweislich nicht im Bundesgebiet an Endabnehmer). Quellen: Art. 45 Abs. 1 PPWR; Leitfaden C(2026) 3702 Abschn. 3 (unverbindliche Auslegung der EU-Kommission); § 7 Abs. 3, § 11 Nr. 4 VerpackDG. Grenze: Anspruchsgrundlage, Verfahren und Nachweisanforderungen der Erstattung im deutschen Recht sind nicht ausdrücklich geregelt – konkrete Durchsetzung ist Einzelfall (Eskalation E02).$q$, 'rollen_epr', array[$q$Art. 45 Abs. 1 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$,$q$§ 7 Abs. 3 VerpackDG$q$,$q$§ 11 Nr. 4 VerpackDG$q$]::text[], 'unverbindliche_auslegung', '{32,8}'::int[], $q$! Erstattungsverfahren ungeregelt → Eskalation$q$, false),
(18, 'A18', $q$Wir exportieren einen Großteil unserer Produktion in die Schweiz. Zählt das irgendwie ins deutsche System rein?$q$, $q$Einordnung: Nein. Die erweiterte Herstellerverantwortung knüpft an die Bereitstellung im Hoheitsgebiet eines Mitgliedstaats an (Art. 45 Abs. 1 PPWR); wird die Ware in ein Drittland exportiert, wo sie zu Abfall wird, entsteht in keinem Mitgliedstaat eine Herstellerrolle (Leitfaden Abschn. 3: bei Export „no producer in any Member State“). Folge: Exportmengen sind nicht systembeteiligungspflichtig; dokumentieren Sie die Exporte nachprüfbar (Ausnahme § 11 Nr. 4 VerpackDG: Verpackungen, die nachweislich nicht im Bundesgebiet an Endabnehmer abgegeben werden) und halten Sie die Mengentrennung in Datenmeldung und Vollständigkeitserklärung durch. Die Konformitätsschiene ist davon unabhängig: Für das Inverkehrbringen IN der Union (auch wenn ein Teil später exportiert wird) gelten die Art.-5-bis-12-Anforderungen ab dem Inverkehrbringen. Quellen: Art. 45 Abs. 1 PPWR; § 11 Nr. 4 VerpackDG; Leitfaden C(2026) 3702 Abschn. 3 (unverbindliche Auslegung). Grenze: Bei Re-Importen beginnt die Betrachtung mit dem letzten Importvorgang neu (so auch EUNR-Papier, Sekundärquelle).$q$, 'rollen_epr', array[$q$Art. 45 Abs. 1 PPWR$q$,$q$§ 11 Nr. 4 VerpackDG$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$,$q$EUNR-Papier Producer Definition (Sekundärquelle)$q$]::text[], 'rechtsverbindlich', '{32,8}'::int[], null, true),
(19, 'A19', $q$Als Importeur war ich nach VerpackG automatisch „Hersteller“. Welche Hüte trage ich denn jetzt alle?$q$, $q$Einordnung: Typischerweise drei. (1) Importeur nach Art. 3 Abs. 1 Nr. 17 PPWR mit eigenen Konformitäts-Prüfpflichten: Sie dürfen nur Verpackungen in Verkehr bringen, bei denen der Erzeuger Konformitätsbewertung, Doku und Kennzeichnung erledigt hat, und müssen Ihre eigenen Kontaktangaben ergänzen (Art. 18, insb. Abs. 3). (2) Hersteller (EPR) nach Nr. 15 lit. b, weil Sie die importierte Ware erstmals im Bundesgebiet bereitstellen: Registrierung, Systembeteiligung, Datenmeldung (§§ 6, 7, 9 VerpackDG). (3) Bei Eigenmarke oder konformitätsrelevanter Veränderung gelten Sie zusätzlich als ERZEUGER mit allen Art.-15-Pflichten (Art. 21 PPWR). Folge: Rollen-Set je Produktlinie klären; unter dem VerpackG war „Importeur = Hersteller“ eine Rolle, jetzt sind es getrennte Pflichtenkreise mit unterschiedlichen Rechtsfolgen. Quellen: Art. 3 Abs. 1 Nr. 15 lit. b u. Nr. 17, Art. 18, Art. 21 PPWR; §§ 6, 7, 9 VerpackDG. Grenze: Bei Kleinstunternehmen-Importeuren mit EU-Lieferant verschiebt Art. 21 UAbs. 2 die Erzeuger-Zurechnung auf den Lieferanten.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. b u. Nr. 17 PPWR$q$,$q$Art. 18 PPWR$q$,$q$Art. 21 PPWR$q$,$q$§§ 6, 7, 9 VerpackDG$q$]::text[], 'rechtsverbindlich', '{37,8,31,32}'::int[], null, true),
(20, 'A20', $q$Wir sind Händler und verkaufen zugekaufte Ware unter unserer Eigenmarke weiter. Heißt das wirklich, wir müssen jetzt Konformitätserklärungen für die Verpackungen ausstellen?$q$, $q$Einordnung: Ja. Bringt ein Importeur oder Vertreiber Verpackungen unter eigenem Namen oder eigener Marke in Verkehr, gilt er als Erzeuger und unterliegt den Erzeuger-Pflichten nach Art. 15 (Art. 21 UAbs. 1 PPWR) – also Konformitätsbewertung (Art. 38), technische Dokumentation (Anhang VII) und EU-Konformitätserklärung (Art. 39, Muster Anhang VIII, je Verpackungstyp). Dasselbe gilt, wenn Sie bereits in Verkehr gebrachte Verpackungen so verändern, dass die Konformität beeinträchtigt sein kann. Folge: Eigenmarken-Sortiment inventarisieren, je Verpackungstyp Bewertung und Doku aufsetzen; Zulieferinformationen können Sie über die Lieferanten-Informationspflicht (Art. 16) einfordern. Sonderfall: Sind Sie Kleinstunternehmen und sitzt Ihr Verpackungslieferant in der Union, gilt der Lieferant als Erzeuger für die Art.-15-Zwecke (Art. 21 UAbs. 2). Quellen: Art. 21, Art. 15, Art. 16, Art. 38, Art. 39 PPWR. Grenze: Die EPR-Herstellerrolle ist separat zu prüfen – Eigenmarke allein sagt darüber nichts (A03).$q$, 'konformitaet', array[$q$Art. 21 PPWR$q$,$q$Art. 15 PPWR$q$,$q$Art. 16 PPWR$q$,$q$Art. 38 u. 39 PPWR$q$]::text[], 'rechtsverbindlich', '{8,4,5,6,40}'::int[], null, true),
(21, 'A21', $q$Unsere Firmengruppe hat drei GmbHs, die alle Ware in Deutschland verkaufen. Reicht eine Registrierung für den Konzern?$q$, $q$Einordnung: Nein. Hersteller ist „jede natürliche oder juristische Person“, die einen Tatbestand des Art. 3 Abs. 1 Nr. 15 PPWR erfüllt – die Rolle entsteht je Rechtsträger, nicht je Konzern. Jede GmbH, die selbst erstmals im Bundesgebiet bereitstellt (oder auspackt, lit. e), ist eigenständig registrierungspflichtig (§ 6 Abs. 1 VerpackDG) und muss ihre eigenen Marken und Verpackungsmengen angeben (§ 6 Abs. 2 Nr. 5 u. 6); die Registrierung ist höchstpersönlich und nicht auf Dritte – auch nicht auf die Konzernmutter – delegierbar (§ 5 Abs. 1 Satz 2). Folge: Drei bereitstellende GmbHs, drei Registrierungen, drei Datenmeldungs-Stränge; konzerninterne Lieferwege sauber abbilden, damit klar ist, welche Gesellschaft je Produktlinie „erstmals bereitstellt“. Quellen: Art. 3 Abs. 1 Nr. 15 PPWR; § 5 Abs. 1 Satz 2, § 6 Abs. 1 u. 2 VerpackDG. Grenze: Welche Gesellschaft bei mehrstufigen Intercompany-Ketten die erste Bereitstellung vornimmt, hängt von den konkreten Liefer- und Abgabebeziehungen ab (bei Unklarheit: Eskalation).$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 PPWR$q$,$q$§ 5 Abs. 1 Satz 2 VerpackDG$q$,$q$§ 6 Abs. 1 u. 2 VerpackDG$q$]::text[], 'rechtsverbindlich', '{31,8}'::int[], null, true),
(22, 'A22', $q$Wir füllen unsere eigene Limo ab und verkaufen sie an den deutschen Handel. Sind wir jetzt Erzeuger ODER Hersteller?$q$, $q$Einordnung: Beides – die Doppelrolle ist der Normalfall des inländischen Markenabfüllers. Erzeuger sind Sie, weil die Verkaufsverpackung unter Ihrem Namen befüllt/versiegelt und in Verkehr gebracht wird (Art. 3 Abs. 1 Nr. 13 PPWR; Leitfaden Abschn. 2: Abfüller mit finalen Verarbeitungsschritten). Hersteller sind Sie, weil Sie das verpackte Produkt erstmals im Bundesgebiet bereitstellen (Nr. 15 lit. b). Folge: Konformitätsschiene (Bewertung Art. 38, Doku Anhang VII, Erklärung Art. 39, Kennzeichnung Art. 15 Abs. 5/6) UND EPR-Schiene (Registrierung § 6, Systembeteiligung § 7, Datenmeldung § 9, ggf. Vollständigkeitserklärung § 10 VerpackDG) laufen parallel; bei pfandpflichtigen Einweg-Getränkeverpackungen zusätzlich §§ 46/47 statt Systembeteiligung (§ 11 Nr. 2). Quellen: Art. 3 Abs. 1 Nr. 13 u. 15 lit. b PPWR; §§ 6, 7, 9, 10, 11 Nr. 2, 46, 47 VerpackDG; Leitfaden Abschn. 2/3. Grenze: Für Export- und Fernabsatzmengen gelten A16/A12.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 13 PPWR$q$,$q$Art. 3 Abs. 1 Nr. 15 lit. b PPWR$q$,$q$§§ 6, 7, 9, 10 VerpackDG$q$,$q$§ 11 Nr. 2 VerpackDG$q$]::text[], 'rechtsverbindlich', '{8,22,31,32,36}'::int[], null, true),
(23, 'A23', $q$Wir kaufen Stretchfolie und Paletten bei einem Händler in den Niederlanden und wickeln damit unsere Ware. Ist der Niederländer dann bei uns der „Hersteller“, weil er direkt an uns als Endkunden liefert?$q$, $q$Einordnung: Nach der Verbandsauslegung nein. Der Fernabsatz-Tatbestand des Art. 3 Abs. 1 Nr. 15 lit. c PPWR setzt eine Lieferung „direkt an Endabnehmer“ voraus. Endabnehmer ist, wem ein Produkt bereitgestellt wird und wer es nicht in der gelieferten Form weiter bereitstellt (Nr. 23). Das EUNR-Papier stellt für lit. c auf den Endabnehmer des PRODUKTS ab: Ein Befüller, der Paletten oder Stretchfolie aus dem EU-Ausland bezieht, um seine Ware zu verpacken, ist für dieses Verpackungsmaterial KEIN Endabnehmer – die Verpackung geht mit der Ware weiter. Folge (nach dieser Lesart): Der niederländische Händler wird nicht über lit. c deutscher Hersteller; als erstes Glied der deutschen Lieferkette rückt vielmehr der inländische Verwender in die Herstellerrolle für diese Transportverpackung. Quellen: Art. 3 Abs. 1 Nr. 15 lit. c u. Nr. 23 PPWR; EUNR-Papier „Producer Definition“ (Juni 2026) – ausdrücklich Sekundärquelle/Verbandsauslegung; Leitfaden Abschn. 3 stützt die Produkt-Endabnehmer-Lesart nur implizit. Grenze: Genau diese Zurechnungskette ist offener Punkt U4 der Rollen-Engine – vor Cattwyk-Bestätigung keine verbindliche Auskunft im Produkt; Assistant antwortet mit Eskalationshinweis.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 15 lit. c PPWR$q$,$q$Art. 3 Abs. 1 Nr. 23 PPWR$q$,$q$EUNR-Papier Producer Definition (Sekundärquelle)$q$,$q$Leitfaden C(2026) 3702 Abschn. 3$q$]::text[], 'unverbindliche_auslegung', '{8,27}'::int[], $q$! U4: Session-Pflicht, bis dahin nicht_ausspielen$q$, false),
(24, 'A24', $q$Was heißt eigentlich „Endvertreiber“ – ist das dasselbe wie unser alter „Letztvertreiber“?$q$, $q$Einordnung: Funktional ja, terminologisch neu. Endvertreiber ist die Person in der Lieferkette, die verpackte Produkte – auch im Wege der Wiederverwendung oder als Wiederbefüllung – an den Endabnehmer liefert (Art. 3 Abs. 1 Nr. 21 PPWR); das erfasst stationären Handel, Gastronomie und Fernabsatz gleichermaßen. Folge: Am Endvertreiber hängen die Praxispflichten am Point of Sale: EINWEG/MEHRWEG-Hinweisschilder in Preisauszeichnungsgröße, auch im Fernabsatz (§ 47 VerpackDG), Pfand-Rücknahme und -Erstattung (§ 46 Abs. 2), Mehrwegangebotspflicht für To-go (§ 60), Tragetaschenverbot (§ 12 Abs. 1), Rücknahmepflichten beschränkt auf das eigene Sortiment (§ 39 Abs. 1 Satz 2) sowie künftig die Mehrwegquote für Getränke (Art. 29 Abs. 6 PPWR ab 2030). Zusätzlich gelten die allgemeinen Vertreiber-Sorgfaltspflichten (Art. 19 PPWR, § 13 Abs. 3 VerpackDG). Quellen: Art. 3 Abs. 1 Nr. 21, Art. 19, Art. 29 Abs. 6 PPWR; §§ 12 Abs. 1, 13 Abs. 3, 39 Abs. 1, 46, 47, 60 VerpackDG. Grenze: Keine.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 21 PPWR$q$,$q$Art. 19 PPWR$q$,$q$§§ 46, 47, 60 VerpackDG$q$,$q$§ 12 Abs. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{36,29,25,38}'::int[], null, true),
(25, 'A25', $q$Gibt es eigentlich EINE Rolle, die für unsere ganze Firma gilt, oder müssen wir das wirklich für jede Produktlinie einzeln durchdeklinieren?$q$, $q$Einordnung: Es gibt keine pauschale Firmenrolle. Alle Rollen der PPWR (Erzeuger, Hersteller, Importeur, Vertreiber, Endvertreiber, Lieferant, Fulfilment-Dienstleister) knüpfen an konkrete Tätigkeiten in Bezug auf konkrete Verpackungen an (Art. 3 Abs. 1 Nr. 12–21 PPWR); der Hersteller ist zudem bewusst KEIN eigener Wirtschaftsakteur, sondern eine Querschnittsrolle aus Erzeuger, Importeur oder Vertreiber (Nr. 12 i. V. m. Nr. 15). Dasselbe Unternehmen kann daher je Produktlinie unterschiedliche Rollen-Sets tragen – etwa Erzeuger+Hersteller bei der Eigenproduktion, nur Vertreiber bei Handelsware, Importeur+Hersteller bei Drittlandsware. Folge: Rollenbestimmung je Produktlinie anhand der Tätigkeiten (genau das leistet der Onboarding-Wizard); Pflichten, Fristen und Risiken ergeben sich erst aus dem jeweiligen Set. Quellen: Art. 3 Abs. 1 Nr. 12–21 PPWR; Systematik bestätigt in Leitfaden C(2026) 3702 Abschn. 2–4. Grenze: Keine.$q$, 'rollen_epr', array[$q$Art. 3 Abs. 1 Nr. 12–21 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 2–4$q$]::text[], 'rechtsverbindlich', '{8}'::int[], null, true),
(26, 'B01', $q$Gilt unsere alte LUCID-Registrierung noch, oder müssen wir uns komplett neu registrieren?$q$, $q$Einordnung: Sie gilt fort. Wer nach § 9 VerpackG (Fassung bis 11.08.2026) registriert ist, gilt auch nach § 6 VerpackDG als registriert (§ 68 Abs. 2 Satz 1 VerpackDG). Folge: Keine Neuregistrierung – aber eine Pflicht zur Aktualisierung: Änderungen der Registrierungsdaten nach neuem Recht (z. B. neue Angaben nach § 6 Abs. 2, etwa zum EHV-Bevollmächtigten oder zur neuen Verpackungs-Aufschlüsselung inkl. § 39-Verpackungen und Pfand-Verpackungen) sind bis zum 12. November 2026 vorzunehmen (§ 68 Abs. 2 Satz 2). Prüfen Sie außerdem, ob durch den Rollen-Systemwechsel zusätzliche Registrierungstatbestände entstanden sind (z. B. Auspacker-Fälle – dann gilt B02). Quellen: § 68 Abs. 2 Satz 1 u. 2, § 6 Abs. 1 u. 2 VerpackDG. Grenze: Die Fortgeltung betrifft die Registrierung als solche; sie heilt keine inhaltlich falsche oder unvollständige Alt-Registrierung.$q$, 'rollen_epr', array[$q$§ 68 Abs. 2 Satz 1 u. 2 VerpackDG$q$,$q$§ 6 Abs. 1 u. 2 VerpackDG$q$]::text[], 'rechtsverbindlich', '{31,8}'::int[], null, true)
on conflict (nr) do nothing;insert into auslegungen (nr, code, frage, antwort, kategorie, quellen, verbindlichkeit, bezug_nr, flag, ausspielen) values
(27, 'B02', $q$Durch die neue Auspacker-Regel sind wir wohl erstmals registrierungspflichtig. Bis wann müssen wir das erledigt haben?$q$, $q$Einordnung: Für Bestands-Konstellationen gibt es eine Nachfrist: Hersteller, die nach § 6 Abs. 1 VerpackDG erstmals registrierungspflichtig sind und nicht bereits nach § 9 VerpackG a. F. registrierungspflichtig waren, müssen sich bis zum 12. September 2026 registrieren (§ 68 Abs. 2 Satz 3). Folge: Wenn Ihre Auspack-Tätigkeit schon vor dem 12.08.2026 lief, haben Sie bis 12.09.2026 Zeit; nehmen Sie die Tätigkeit dagegen erst neu auf, gilt die reguläre Regel „Registrierung VOR dem Auspacken“ (§ 6 Abs. 1 Satz 1). Beachten Sie die Sanktionslage: Das Auspack-/Bereitstellungsverbot ohne Registrierung (§ 13 Abs. 1) und die nationalen Bußgeldtatbestände (§ 66 Abs. 1) gelten bereits seit 12.08.2026 – die Nachfrist ist eine Registrierungsfrist, kein Freibrief für andere Pflichten (insbesondere Systembeteiligung vor dem Auspacken, § 7 Abs. 1). Quellen: § 68 Abs. 2 Satz 3, § 6 Abs. 1, § 7 Abs. 1, § 13 Abs. 1, § 66 Abs. 1 VerpackDG. Grenze: Ob eine Konstellation „bereits nach § 9 VerpackG registrierungspflichtig“ war, kann im Einzelfall streitig sein – im Zweifel früh registrieren.$q$, 'rollen_epr', array[$q$§ 68 Abs. 2 Satz 3 VerpackDG$q$,$q$§ 6 Abs. 1 VerpackDG$q$,$q$§ 13 Abs. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{31,8}'::int[], null, true),
(28, 'B03', $q$Unser Systemvertrag mit dem dualen System läuft noch bis Ende 2027. Können wir den einfach weiterlaufen lassen?$q$, $q$Einordnung: Nur begrenzt. Systembeteiligungen nach § 7 VerpackG a. F., die vor dem 12.08.2026 erfolgt sind, gelten – vorbehaltlich abweichender privatrechtlicher Vereinbarungen – fort, längstens jedoch bis zum Ablauf des 31. Dezember 2026 (§ 68 Abs. 1 VerpackDG). Folge: Spätestens zum 01.01.2027 brauchen Sie eine Systembeteiligung nach neuem Recht (§ 7 Abs. 1 VerpackDG); planen Sie die Vertragsmigration im Q4/2026, inklusive der neuen Mengen-/Rollenabgrenzung (Export-Ausnahme § 11 Nr. 4, geänderte Herstellerzuordnung je Produktlinie). Ohne wirksame Beteiligung ab 2027 drohen Bereitstellungsverbot (§ 13 Abs. 1 Satz 2) und Bußgeld (§ 66 Abs. 1). Quellen: § 68 Abs. 1, § 7 Abs. 1, § 13 Abs. 1, § 66 Abs. 1 VerpackDG. Grenze: Was Ihr konkreter Vertrag zivilrechtlich für die Umstellung vorsieht (Laufzeit, Anpassungsklauseln), ist Vertragsprüfung im Einzelfall.$q$, 'rollen_epr', array[$q$§ 68 Abs. 1 VerpackDG$q$,$q$§ 7 Abs. 1 VerpackDG$q$,$q$§ 13 Abs. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{32,31}'::int[], null, true),
(29, 'B04', $q$Stimmt das Gerücht, dass es bis Anfang 2027 sowieso keine Bußgelder gibt und wir uns Zeit lassen können?$q$, $q$Einordnung: Das Gerücht verkürzt gefährlich. Richtig ist nur: Die Bußgeldtatbestände für Verstöße gegen die PPWR selbst (§ 66 Abs. 2 VerpackDG) sind erst ab dem 12. Februar 2027 anzuwenden (§ 68 Abs. 17). Falsch ist der Umkehrschluss: Die NATIONALEN Bußgeldtatbestände (§ 66 Abs. 1 – z. B. fehlende Registrierung, fehlende Systembeteiligung, Pfand- und Hinweispflichtverstöße) gelten seit dem 12.08.2026. Unabhängig von Bußgeldern gelten ab sofort außerdem: Vertriebs-, Bereitstellungs- und Auspackverbote (§ 13), zivilrechtliche Abmahnrisiken und die volle Marktüberwachung nach der PPWR (Art. 58 ff.). Folge: Die Zeitschiene ist eine Sanktions-Staffelung, keine Schonfrist – Pflichten bestehen seit 12.08.2026. Quellen: § 66 Abs. 1 u. 2, § 68 Abs. 17, § 13 VerpackDG; Art. 58 ff. PPWR. Grenze: Keine.$q$, 'sonstiges', array[$q$§ 66 Abs. 1 u. 2 VerpackDG$q$,$q$§ 68 Abs. 17 VerpackDG$q$,$q$§ 13 VerpackDG$q$]::text[], 'rechtsverbindlich', '{8,31,32,10}'::int[], null, true),
(30, 'B05', $q$Wie läuft das mit der Vollständigkeitserklärung für 2026 – nach altem oder neuem Recht?$q$, $q$Einordnung: Nach neuem Recht, ohne Doppelabgabe. Für Verpackungen, die im Kalenderjahr 2026 im Bundesgebiet bereitgestellt wurden, gilt ausschließlich § 10 VerpackDG; eine zusätzliche Vollständigkeitserklärung nach § 11 VerpackG a. F. ist für 2026 nicht zu hinterlegen (§ 68 Abs. 5 Satz 3 u. 4). Für die Aufschlüsselung der 2026er-Angaben gelten übergangsweise die alten Einordnungsmaßstäbe fort (§ 68 Abs. 5 Satz 5). Alt-Hersteller nach VerpackG-Logik, die nach neuem Recht keine Hersteller mehr sind, bleiben für ihre 2026er-Alt-Mengen entsprechend melde- und VE-pflichtig (§ 68 Abs. 5 Satz 1). Folge: VE für das Berichtsjahr 2026 bis zum 15. Mai 2027 über die ZSVR-Plattform, geprüft durch registrierten Sachverständigen bzw. Prüfer (§ 10 Abs. 1); Prüfer-Slot früh sichern. Quellen: § 68 Abs. 5, § 10 Abs. 1 u. 3, § 56 VerpackDG. Grenze: (!) § 66 Abs. 1 Nr. 6/7 verweisen für die Bußgeldbewehrung auf „§ 68 Absatz 3 Satz 1“, während die VE-Übergangsregel in Abs. 5 steht – dieses Zitat ist in der Session zu klären (mögliches Redaktionsversehen; Eskalation E06).$q$, 'rollen_epr', array[$q$§ 68 Abs. 5 VerpackDG$q$,$q$§ 10 Abs. 1 u. 3 VerpackDG$q$,$q$§ 66 Abs. 1 Nr. 6 u. 7 VerpackDG$q$]::text[], 'rechtsverbindlich', '{33}'::int[], $q$! E06: Verweis § 66 Abs. 1 Nr. 6/7 auf § 68 Abs. 3 prüfen$q$, false),
(31, 'B06', $q$Ab welchen Mengen brauchen wir überhaupt eine Vollständigkeitserklärung?$q$, $q$Einordnung: Die Schwellen stehen jetzt in § 10 Abs. 4 VerpackDG: Befreit ist, wer systembeteiligungspflichtige Verpackungen im vorangegangenen Kalenderjahr höchstens in folgenden Mengen im Bundesgebiet bereitgestellt hat – Glas unter 80 Tonnen, Papier/Pappe/Karton unter 50 Tonnen, übrige Materialarten (nach § 42 Abs. 2 Satz 1) unter 30 Tonnen. Folge: Liegen Sie in ALLEN Fraktionen unter den Schwellen, entfällt die Hinterlegungspflicht; ZSVR oder Landesbehörde können die VE aber unabhängig davon jederzeit mit Fristsetzung verlangen (§ 10 Abs. 4 Satz 2). Oberhalb der Schwellen: jährlich bis 15. Mai, elektronisch, mit Prüfbestätigung (registrierter Sachverständiger oder registrierter Wirtschaftsprüfer/Steuerberater/vereidigter Buchprüfer, § 10 Abs. 1 u. 3, § 56 Abs. 2). Quellen: § 10 Abs. 1, 3 u. 4, § 56 Abs. 2 VerpackDG. Grenze: Die Schwellen betreffen nur die VE; Datenmeldungen nach § 9 laufen unabhängig (Erleichterung erst unter 10 t Gesamtmenge, B07).$q$, 'rollen_epr', array[$q$§ 10 Abs. 4 VerpackDG$q$,$q$§ 10 Abs. 1 u. 3 VerpackDG$q$,$q$§ 56 Abs. 2 VerpackDG$q$]::text[], 'rechtsverbindlich', '{33}'::int[], null, true),
(32, 'B07', $q$Müssen wir wirklich jede einzelne Systemmeldung sofort parallel an die ZSVR schicken? Wir sind ein Kleinbetrieb.$q$, $q$Einordnung: Grundsatz ja, mit Kleinmengen-Erleichterung. Hersteller müssen die im Rahmen der Systembeteiligung getätigten Angaben (Registrierungsnummer, Materialart/Masse, System, Zeitraum) unverzüglich nach Übermittlung an das System auch der ZSVR melden (§ 9 Abs. 1 VerpackDG). ABER: Wer im Vorjahr insgesamt weniger als 10 Tonnen systembeteiligungspflichtige Verpackungen bereitgestellt (bzw. nach Nr. 15 lit. e ausgepackt) hat, ist von der laufenden Spiegelmeldung befreit und meldet stattdessen sämtliche Angaben gebündelt bis zum 1. Juni des Folgejahres (§ 9 Abs. 2). Folge: Vorjahresmenge prüfen; unter 10 t genügt die Jahres-Sammelmeldung. Wichtig: Die Meldung ist höchstpersönlich – Datenmeldungen nach § 9 sind nicht auf Dritte delegierbar (§ 5 Abs. 1 Satz 2). Quellen: § 9 Abs. 1 u. 2, § 5 Abs. 1 Satz 2 VerpackDG. Grenze: Die 10-t-Erleichterung ändert nichts an der Systembeteiligung selbst und nicht an der VE-Prüfung nach B06.$q$, 'rollen_epr', array[$q$§ 9 Abs. 1 u. 2 VerpackDG$q$,$q$§ 5 Abs. 1 Satz 2 VerpackDG$q$]::text[], 'rechtsverbindlich', '{33}'::int[], null, true),
(33, 'B08', $q$Was ändert sich beim Pfand? Wir bringen Säfte und Limonaden in Flaschen und Dosen in den Handel.$q$, $q$Einordnung: Inhaltlich weitgehend Kontinuität, jetzt in §§ 46/47 VerpackDG. Es bleibt beim Mindestpfand von 0,25 € je Einweggetränkeverpackung, der Pfandkennzeichnung vor der Bereitstellung, der Teilnahme am bundesweit einheitlichen Pfandsystem und den Rücknahme-/Erstattungspflichten auf allen Handelsstufen (§ 46 Abs. 1–3). Der Ausnahmenkatalog steht in § 46 Abs. 4 (u. a. unter 0,1 l, über 3,0 l, bestimmte Getränkekartons, Milch- und Wein-Tatbestände) – ABER mit Rückausnahme: Die Getränke-Ausnahmen der Nr. 7 gelten NICHT, wenn in Kunststoff-Einwegflaschen oder Dosen abgefüllt wird (§ 46 Abs. 4 Satz 2) – Ihre Säfte in PET/Dose sind also pfandpflichtig. Folge: Sortiment gegen § 46 Abs. 4 prüfen; pfandpflichtige Verpackungen sind von der Systembeteiligung ausgenommen (§ 11 Nr. 2), die Registrierung nach § 6 bleibt. Getrenntsammelziel für Kunststoff-Einwegflaschen: 77 %, ab 2029 90 % (§ 46 Abs. 5 Satz 3). Quellen: §§ 46, 47, § 11 Nr. 2, § 6 VerpackDG; EU-Rahmen Art. 50 PPWR. Grenze: Einzelne Getränke-Einordnungen (z. B. Milchmisch-Anteile) sind Rezepturfragen des Einzelfalls.$q$, 'rollen_epr', array[$q$§ 46 Abs. 1–5 VerpackDG$q$,$q$§ 47 VerpackDG$q$,$q$§ 11 Nr. 2 VerpackDG$q$,$q$Art. 50 PPWR$q$]::text[], 'rechtsverbindlich', '{36,31}'::int[], null, true),
(34, 'B09', $q$Brauchen wir die EINWEG/MEHRWEG-Schilder auch im Onlineshop – und wie groß müssen die sein?$q$, $q$Einordnung: Ja. Die Hinweispflichten der Endvertreiber (EINWEG bei pfandpflichtigen Einweg-Getränkeverpackungen, MEHRWEG bei wiederverwendbaren Getränkeverpackungen) gelten im Fernabsatz entsprechend – die Hinweise sind in den jeweils verwendeten Darstellungsmedien zu geben (§ 47 Abs. 1–3 VerpackDG), also z. B. auf der Produktseite. Größenvorgabe: Die Hinweise müssen in Gestalt und Schriftgröße mindestens der Preisauszeichnung des jeweiligen Produkts entsprechen (§ 47 Abs. 4). Ausgenommen sind Endvertreiber, die für die betreffenden Getränkeverpackungen von der Grundpreisangabe befreit sind (§ 47 Abs. 5), sowie MEHRWEG-Hinweise bei Gebinden über 3,0 l oder den Getränken des § 46 Abs. 4 Nr. 7 (§ 47 Abs. 2 Satz 2). Folge: Shop-Templates prüfen – der fehlende oder zu kleine Online-Hinweis ist ein klassischer Abmahnfall und seit 12.08.2026 nach § 66 Abs. 1 Nr. 26 bußgeldbewehrt. Quellen: § 47 Abs. 1–5, § 66 Abs. 1 Nr. 26 VerpackDG. Grenze: Keine.$q$, 'kennzeichnung', array[$q$§ 47 Abs. 1–5 VerpackDG$q$,$q$§ 66 Abs. 1 Nr. 26 VerpackDG$q$]::text[], 'rechtsverbindlich', '{36}'::int[], null, true),
(35, 'B10', $q$Im Gesetz taucht neben dem „Hersteller“ auch noch der „Erstinverkehrbringer“ auf. Ist das nicht dasselbe?$q$, $q$Einordnung: Nein – Vorsicht Begriffsfalle. „Erstinverkehrbringer“ (jede Person, die Verpackungen erstmals gewerbsmäßig im Bundesgebiet bereitstellt) und „Inverkehrbringer“ sind rein nationale Hilfsbegriffe des § 3 Abs. 17 u. 18 VerpackDG; sie steuern punktuell einzelne Normen – vor allem die Pfandpflichten (§ 46: Pfanderhebung/Kennzeichnung durch den Erstinverkehrbringer, Pfandkette über alle Inverkehrbringer) und Bereitstellungsbeschränkungen. Die PPWR-Rollen Hersteller/Erzeuger sind davon getrennt definiert und lösen die EPR- bzw. Konformitätspflichten aus. Meist fallen Hersteller (Nr. 15 lit. a/b) und Erstinverkehrbringer zusammen, aber nicht zwingend (z. B. beim Auspacker-Tatbestand lit. e). Folge: In Verträgen und internen Prozessen sauber trennen, welche Norm an welchen Begriff anknüpft; im Nutzer-Frontend weisen wir die nationalen Hilfsbegriffe nicht als eigene Rollen aus. Quellen: § 3 Abs. 17 u. 18, § 46 VerpackDG; Art. 3 Abs. 1 Nr. 13 u. 15 PPWR. Grenze: Keine.$q$, 'rollen_epr', array[$q$§ 3 Abs. 17 u. 18 VerpackDG$q$,$q$§ 46 VerpackDG$q$,$q$Art. 3 Abs. 1 Nr. 13 u. 15 PPWR$q$]::text[], 'rechtsverbindlich', '{8,36}'::int[], null, true),
(36, 'B11', $q$Für unsere Mehrwegkisten haben wir nie lizenziert. Bleibt das so – und müssen wir trotzdem irgendwo gemeldet sein?$q$, $q$Einordnung: Beides ja. Die Systembeteiligungspflicht (und §§ 8–10) gilt nicht für Hersteller wiederverwendbarer Verpackungen, deren tatsächliche Rücknahme und Wiederverwendung durch ein bestehendes Wiederverwendungssystem ermöglicht wird (§ 11 Nr. 1 VerpackDG). Die Registrierungspflicht bleibt davon aber unberührt: § 6 Abs. 1 erfasst Hersteller ALLER Verpackungen, und die Registrierungsangaben schlüsseln ausdrücklich auch die § 39-Verpackungen auf, zu denen Mehrweg gehört (§ 6 Abs. 2 Nr. 6 i. V. m. § 39 Abs. 1 Satz 1 Nr. 6). Zusätzlich treffen Sie die Rücknahme- und Verwertungspflichten für Mehrweg (§ 39 Abs. 1 Satz 1 Nr. 6) und – auf EU-Ebene – die Mehrweg-Anforderungen des Art. 11 i. V. m. Anhang VI PPWR samt Systemzugehörigkeit. Folge: Registrierung prüfen/aktualisieren; Nachweis des funktionierenden Wiederverwendungssystems dokumentieren, denn er trägt die § 11-Nr. 1-Ausnahme. Quellen: § 11 Nr. 1, § 6 Abs. 1 u. 2 Nr. 6, § 39 Abs. 1 Satz 1 Nr. 6 VerpackDG; Art. 11, Anhang VI PPWR. Grenze: Zur Frage, wann ein System „funktionierend“ ist, siehe C07 (teils Auslegung).$q$, 'mehrweg', array[$q$§ 11 Nr. 1 VerpackDG$q$,$q$§ 6 Abs. 1 u. 2 VerpackDG$q$,$q$§ 39 Abs. 1 Satz 1 Nr. 6 VerpackDG$q$,$q$Art. 11 PPWR$q$]::text[], 'rechtsverbindlich', '{31,3,30,34}'::int[], null, true),
(37, 'B12', $q$Unsere B2B-Transportverpackungen landen nie beim Privatkunden. Sind wir da wirklich komplett raus?$q$, $q$Einordnung: Aus der Systembeteiligung meist ja, aus dem Pflichtenkreis nein. Systembeteiligungspflichtig sind nur Verpackungen, die typischerweise mehrheitlich in privaten Haushaltungen oder vergleichbaren Anfallstellen als Abfall anfallen (§ 3 Abs. 6 VerpackDG) – reine B2B-Transportverpackungen regelmäßig nicht. Es bleiben aber: (1) Registrierung nach § 6 (gilt für alle Verpackungen, Aufschlüsselung nach § 39-Kategorien), (2) unentgeltliche Rücknahme gebrauchter, restentleerter Verpackungen gleicher Art/Form/Größe am Übergabeort plus Verwertung und jährlicher Nachweis bis 15. Mai (§ 39 Abs. 1 u. 3, § 42), (3) perspektivisch die Zulassungspflicht nach § 19 – übergangsweise dürfen Hersteller nicht systembeteiligungspflichtiger Verpackungen noch bis 31.12.2027 ohne Zulassung bereitstellen (§ 68 Abs. 9). Achtung „vergleichbare Anfallstellen“: Gastronomie, Verwaltungen, viele Handwerksbetriebe zählen zum haushaltsnahen Anfall (§ 3 Abs. 7) – die B2B-Einstufung ist je Verpackung zu prüfen. Quellen: § 3 Abs. 6 u. 7, § 6, § 39 Abs. 1 u. 3, § 19, § 68 Abs. 9 VerpackDG. Grenze: Einstufungs-Zweifelsfälle sind ZSVR-Einordnungspraxis (Eskalation möglich).$q$, 'rollen_epr', array[$q$§ 3 Abs. 6 u. 7 VerpackDG$q$,$q$§ 39 Abs. 1 u. 3 VerpackDG$q$,$q$§ 19 VerpackDG$q$,$q$§ 68 Abs. 9 VerpackDG$q$]::text[], 'rechtsverbindlich', '{34,31,32}'::int[], null, true),
(38, 'B13', $q$Wir betreiben seit Jahren eine Branchenlösung für unsere Kantinenbelieferung. Fliegt uns die jetzt um die Ohren?$q$, $q$Einordnung: Nein, aber es gibt eine Zulassungs-Uhr. Branchenlösungen bleiben als Erfüllungsweg erhalten (§ 8 VerpackDG: unentgeltliche Rücknahme bei nachweislich belieferten vergleichbaren Anfallstellen statt Systembeteiligung), neu ist eine Zulassungspflicht. Übergang: Wer den Betrieb vor dem 12.08.2026 nach § 8 Abs. 2 VerpackG a. F. angezeigt hatte, darf längstens bis zum 31. Oktober 2027 ohne neue Zulassung weitermachen; dasselbe Enddatum gilt für nach dem 11.08.2026 neu aufgenommene Branchenlösungen (§ 68 Abs. 6 u. 7). Folge: Zulassungsverfahren (§ 8 Abs. 3 i. V. m. § 22, inkl. Sachverständigen-Bescheinigung der Erfassungsstruktur, Bestätigungen der Anfallstellen, Finanzierungsvereinbarung) rechtzeitig vor Ende Oktober 2027 anstoßen; Mengenstromnachweis jährlich bis 1. Juni hinterlegen (§ 8 Abs. 5). Quellen: § 8, § 68 Abs. 6 u. 7 VerpackDG. Grenze: Keine.$q$, 'rollen_epr', array[$q$§ 8 VerpackDG$q$,$q$§ 68 Abs. 6 u. 7 VerpackDG$q$]::text[], 'rechtsverbindlich', '{34,32}'::int[], null, true),
(39, 'B14', $q$Als Händler: Müssen wir jetzt wirklich bei jedem Lieferanten prüfen, ob der in LUCID steht, bevor wir seine Ware ins Regal stellen?$q$, $q$Einordnung: Ja, das ist zweifach angeordnet. EU-Ebene: Vertreiber müssen vor der Bereitstellung überprüfen, dass der Hersteller im Herstellerregister des jeweiligen Mitgliedstaats registriert ist (Art. 19 PPWR i. V. m. Art. 44) und dass die Kennzeichnungen nach Art. 15 Abs. 5/6 bzw. Art. 18 Abs. 3 vorhanden sind. Deutsche Ebene: Vertreiber dürfen Verpackungen nicht bereitstellen, wenn die Hersteller nicht ordnungsgemäß registriert sind, und systembeteiligungspflichtige Verpackungen nicht, wenn keine Systembeteiligung besteht (§ 13 Abs. 3 VerpackDG). Das LUCID-Register ist dafür öffentlich einsehbar (§ 6 Abs. 4). Folge: Lieferanten-Onboarding um Registrierungsnummer-Abfrage und Registercheck erweitern (Generator-Checkliste); bei Zweifeln nicht bereitstellen. Praktisch ist die Registrierung damit Listungsvoraussetzung. Quellen: Art. 19, Art. 44 PPWR; § 13 Abs. 3, § 6 Abs. 4 VerpackDG. Grenze: Zum Umfang zumutbarer laufender Kontrollen (Stichproben vs. Vollprüfung) gibt es noch keine Vollzugspraxis.$q$, 'konformitaet', array[$q$Art. 19 PPWR$q$,$q$Art. 44 PPWR$q$,$q$§ 13 Abs. 3 VerpackDG$q$,$q$§ 6 Abs. 4 VerpackDG$q$]::text[], 'rechtsverbindlich', '{38,31}'::int[], null, true)
on conflict (nr) do nothing;insert into auslegungen (nr, code, frage, antwort, kategorie, quellen, verbindlichkeit, bezug_nr, flag, ausspielen) values
(40, 'B15', $q$Ökomodulation: Unser dualer System-Anbieter kündigt neue Zuschläge für schlecht recycelbare Verpackungen an. Dürfen die das einfach?$q$, $q$Einordnung: Sie müssen es sogar. Systeme sind verpflichtet, die Beteiligungsentgelte ökologisch zu gestalten – insbesondere nach Recyclingfähigkeit und Rezyklateinsatz (§ 26 VerpackDG); die Detailvorgaben kommen per Rechtsverordnung nach § 26a, bis dahin bleibt der ZSVR-Mindeststandard Recyclingfähigkeit Bemessungsmaßstab (§ 26a Abs. 2 Nr. 1 lit. a). Der EU-Rahmen dafür ist Art. 45 PPWR i. V. m. den EPR-Grundsätzen der Abfallrahmenrichtlinie. Folge: Die Entgeltdifferenzierung ist kein Kulanzthema, sondern Regulierungsfolge – für Sie wird die Recyclingfähigkeit je SKU zum direkten Kostenhebel. Konkrete Handlung: Portfolio gegen den aktuellen Mindeststandard raten lassen, Redesign-Kandidaten priorisieren, RVO-Erlass beobachten (Radar R12). Quellen: §§ 26, 26a VerpackDG; Art. 45 PPWR. Grenze: Ob eine konkrete Zuschlagshöhe zulässig kalkuliert ist, ist Vertrags-/Kartellrechtsfrage des Einzelfalls; die Fundstelle des AbfRRL-Bezugs (Art. 8/8a) ist als V16 noch zu pinnen.$q$, 'rollen_epr', array[$q$§ 26 VerpackDG$q$,$q$§ 26a VerpackDG$q$,$q$Art. 45 PPWR$q$]::text[], 'rechtsverbindlich', '{35}'::int[], $q$! V16: AbfRRL-Zitat pinnen$q$, false),
(41, 'C01', $q$Wir haben noch ein volles Lager beschichteter Burger-Boxen aus 2025. Dürfen wir die nach dem Stichtag noch abverkaufen?$q$, $q$Einordnung: Entscheidend ist nicht das Produktionsdatum, sondern das Inverkehrbringen – die ERSTMALIGE Bereitstellung (Art. 3 Abs. 1 Nr. 10 u. 11 PPWR). Lebensmittelkontakt-Verpackungen, die ab dem 12.08.2026 in Verkehr gebracht werden, müssen die PFAS-Grenzwerte des Art. 5 Abs. 5 einhalten; eine Abverkaufsfrist für Lagerbestände sieht die PPWR ausdrücklich nicht vor („no transitional period for the exhaustion of stocks“, Leitfaden Abschn. 5). Folge: Unverkaufte Lagerware bei Ihnen als Erzeuger/Importeur ist noch NICHT in Verkehr gebracht – sie darf ab Stichtag nur bereitgestellt werden, wenn sie konform ist. Was dagegen vor dem 12.08.2026 bereits in Verkehr gebracht wurde (z. B. Ware beim Handel), darf am Markt bleiben und abverkauft werden. Bei Import gilt als Zeitpunkt die zollrechtliche Überlassung zum freien Verkehr (Leitfaden Abschn. 5). Quellen: Art. 3 Abs. 1 Nr. 10 u. 11, Art. 5 Abs. 5 PPWR; Leitfaden C(2026) 3702 Abschn. 5 (unverbindliche Auslegung). Grenze: Die verbreitete Verkürzung „Lagerbestände sind sicher“ ist falsch – bitte nicht weitertragen.$q$, 'stoffrecht', array[$q$Art. 3 Abs. 1 Nr. 10 u. 11 PPWR$q$,$q$Art. 5 Abs. 5 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 5$q$]::text[], 'rechtsverbindlich', '{2,10}'::int[], null, true),
(42, 'C02', $q$Welche PFAS-Grenzwerte gelten genau, und was müssen uns unsere Lieferanten dazu liefern?$q$, $q$Einordnung: Seit 12.08.2026 darf Lebensmittelkontakt-Verpackung nicht in Verkehr gebracht werden, wenn sie PFAS in folgenden Konzentrationen enthält: 25 ppb je Einzelsubstanz (gezielte Analyse, polymere PFAS ausgenommen), 250 ppb als Summe der gezielten Analysen (ggf. nach Vorläufer-Abbau, polymere PFAS ausgenommen), 50 ppm für PFAS einschließlich polymerer PFAS (Art. 5 Abs. 5 lit. a–c PPWR). Lieferkette: Übersteigt der Gesamtfluorgehalt 50 mg/kg, müssen Hersteller, Importeure oder nachgeschaltete Anwender im Sinne der REACH-Verordnung dem Erzeuger/Importeur auf Anfrage den Nachweis liefern, welcher Fluoranteil PFAS bzw. Nicht-PFAS ist – als Grundlage der technischen Dokumentation (Art. 5 Abs. 5 lit. c a. E.). Folge: LMK-Portfolio filtern, Lieferantenerklärungen anfordern (Generator-Muster); als Nachweislogik empfiehlt die Kommission die dreistufige Prüfkaskade Gesamtfluor → Pyrolyse-GC/MS → TOP-Analyse (Leitfaden Abschn. 5 – unverbindliche Empfehlung, keine harmonisierte Methode). Quellen: Art. 5 Abs. 5 PPWR; Leitfaden C(2026) 3702 Abschn. 5. Grenze: Vorrang strengerer anderer EU-Rechtsakte bleibt unberührt (Wortlaut Abs. 5); keine Ausnahme für Rezyklateinsatz.$q$, 'stoffrecht', array[$q$Art. 5 Abs. 5 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 5$q$]::text[], 'rechtsverbindlich', '{2,5,40}'::int[], null, true),
(43, 'C03', $q$Reicht EINE Konformitätserklärung für unser gesamtes Sortiment, und dürfen wir die auf Englisch schreiben?$q$, $q$Einordnung: Eine Sammel-Erklärung „für alle Verpackungen“ genügt nicht: Die EU-Konformitätserklärung ist je Verpackungstyp nach dem Muster des Anhangs VIII auszustellen, aktuell zu halten und mit der technischen Dokumentation zu verknüpfen; mit der Ausstellung übernimmt der Erzeuger die Verantwortung für die Konformität (Art. 39 PPWR). Vorgelagert ist je Typ das Konformitätsbewertungsverfahren nach Art. 38 i. V. m. Anhang VII (Modul A, interne Fertigungskontrolle). Sprache: In Deutschland muss eine unterzeichnete Version nach Wahl des Herstellers in deutscher ODER englischer Sprache vorgehalten werden; eine deutsche Übersetzung ist nur auf Behördenverlangen beizubringen (§ 62 VerpackDG). Folge: Verpackungstypen inventarisieren (Compliance-Profil), je Typ Bewertung dokumentieren, Erklärung aus dem Generator vorbefüllen, unterzeichnen, versioniert ablegen. Quellen: Art. 38, Art. 39, Anhang VII u. VIII PPWR; § 62 VerpackDG. Grenze: Die Absatz-Fundstellen zu Aufbewahrungsfristen und behördlicher Vorlagefrist (Art. 15) sind als V1 noch final zu pinnen – die Pflichten selbst sind unstreitig.$q$, 'konformitaet', array[$q$Art. 38 PPWR$q$,$q$Art. 39 i. V. m. Anhang VIII PPWR$q$,$q$§ 62 VerpackDG$q$]::text[], 'rechtsverbindlich', '{4,5,6}'::int[], $q$! V1: Absatz-Pins Art. 15 offen$q$, false),
(44, 'C04', $q$Bei unserem Private-Label-Geschäft: Wer muss die Konformitätserklärung unterschreiben – und darf das ein externes Labor übernehmen?$q$, $q$Einordnung: Die Erklärung ist Sache des Erzeugers – beim Private Label also des Markeninhabers (Art. 3 Abs. 1 Nr. 13 lit. a, Art. 39 PPWR). Delegation ist zweistufig möglich: (1) Das Konformitätsbewertungsverfahren selbst darf ein Dritter im Auftrag durchführen (z. B. Labor oder Zertifizierungsstelle), die rechtliche Verantwortung bleibt beim Erzeuger (Art. 15 Abs. 2; Leitfaden Abschn. 2: der Erzeuger ist „sole economic operator bearing legal responsibility“). (2) Die Ausstellung der EU-Konformitätserklärung kann ein Bevollmächtigter nach Art. 17 übernehmen, den der Erzeuger schriftlich mandatiert; der Lieferant muss dem Erzeuger dafür alle erforderlichen Informationen und Unterlagen bereitstellen (Art. 16 Abs. 1). Folge: Vertraglich sauber regeln, wer Bewertung, Doku-Zulieferung und Unterschrift übernimmt; das Labor „haftet“ nicht an Ihrer Stelle. Quellen: Art. 3 Abs. 1 Nr. 13 lit. a, Art. 15 Abs. 2, Art. 16 Abs. 1, Art. 17, Art. 39 PPWR; Leitfaden Abschn. 2 (unverbindliche Auslegung). Grenze: Bei Kleinstunternehmen-Markeninhabern verschiebt sich die Erzeuger-Rolle (A04).$q$, 'konformitaet', array[$q$Art. 39 PPWR$q$,$q$Art. 15 Abs. 2 PPWR$q$,$q$Art. 16 Abs. 1 PPWR$q$,$q$Art. 17 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 2$q$]::text[], 'rechtsverbindlich', '{6,4,40}'::int[], null, true),
(45, 'C05', $q$Unsere Mehrweg-Kunststoffkästen reißen wegen des Rezyklateinsatzes den Schwermetall-Grenzwert. Ist das jetzt ein Vertriebsverbot?$q$, $q$Einordnung: Der Summengrenzwert für Blei, Cadmium, Quecksilber und Chrom VI von 100 mg/kg gilt seit 12.08.2026 als PPWR-Pflicht fort (Art. 5 Abs. 4). Deutschland hat aber von einer nationalen Ausnahme Gebrauch gemacht: Für Kunststoffkästen und -paletten gilt die Bereitstellungsbeschränkung im Bundesgebiet NICHT, wenn die Überschreitung allein auf Sekundärrohstoff-Einsatz beruht, die Kästen/Paletten in geschlossenen und kontrollierten Produktkreisläufen zirkulieren, ein Bestandserfassungs- und Kontrollsystem nach § 15 eingerichtet ist und die Herstellung im kontrollierten Verwertungsverfahren erfolgt (§ 14 VerpackDG; für Glas: §§ 17/18 mit 250 mg/kg-Deckel). Dazu gehören Konformitätserklärung und Jahresbericht nach § 16. Folge: Prüfen, ob Ihr Kreislauf die § 14-Kriterien dokumentiert erfüllt – dann kein Vertriebsverbot in Deutschland; für andere EU-Märkte gilt die Ausnahme NICHT. Quellen: Art. 5 Abs. 4 PPWR; §§ 14–16 VerpackDG. Grenze: (!) Die Fortgeltungs-Mechanik (Streichung der §§ 14–18 bei Erlass der delegierten Rechtsakte, Mantelgesetz Art. 4) ist als V2 in der Session zu bestätigen.$q$, 'stoffrecht', array[$q$Art. 5 Abs. 4 PPWR$q$,$q$§§ 14–16 VerpackDG$q$,$q$§§ 17–18 VerpackDG$q$]::text[], 'rechtsverbindlich', '{1}'::int[], $q$! V2: Fortgeltungs-Mechanik bestätigen$q$, false),
(46, 'C06', $q$Wir wollen unsere Transportboxen ab sofort als „Mehrweg“ vermarkten. Reicht es, dass sie stabil sind und mehrfach benutzt werden können?$q$, $q$Einordnung: Nein. Als wiederverwendbar gilt eine Verpackung nur, wenn sie ALLE Kriterien des Art. 11 Abs. 1 lit. a–i PPWR erfüllt (u. a. Konzeption für Mehrfachumläufe, Entleer-/Wiederbefüllbarkeit ohne Beschädigung, Rekonditionierbarkeit nach Anhang VI Teil B, Kennzeichnungsfähigkeit, Recyclingfähigkeit am Lebensende) UND Teil eines Wiederverwendungssystems nach Anhang VI ist. Das gilt materiell für alles, was ab dem 11.02.2025 in Verkehr gebracht wurde; davor in Verkehr gebrachte Mehrwegverpackungen müssen nicht nachgerüstet werden (Art. 15 Abs. 9; Leitfaden Abschn. 12). Folge: Je SKU Kriterien-Check plus Systemnachweis (Rücknahme, Rekonditionierung) dokumentieren – erst dann Mehrweg-Einstufung und die daran hängenden Vorteile (z. B. § 11 Nr. 1 VerpackDG). Falsch-Einstufung kippt in die Einweg-Folgen: Systembeteiligung bzw. Pfandpflicht, falsche Kennzeichnung, Vertriebsrisiko. Quellen: Art. 11 Abs. 1 i. V. m. Anhang VI, Art. 15 Abs. 9 PPWR; Leitfaden C(2026) 3702 Abschn. 12 (unverbindliche Auslegung); § 11 Nr. 1 VerpackDG. Grenze: Mindest-Rotationszahlen kommen erst per delegiertem Rechtsakt (Art. 11 Abs. 2, Radar R3).$q$, 'mehrweg', array[$q$Art. 11 Abs. 1 i. V. m. Anhang VI PPWR$q$,$q$Art. 15 Abs. 9 PPWR$q$,$q$Leitfaden C(2026) 3702 Abschn. 12$q$,$q$§ 11 Nr. 1 VerpackDG$q$]::text[], 'rechtsverbindlich', '{3,30}'::int[], null, true),
(47, 'C07', $q$Müssen wir als Nutzer von Mehrweg-Paletten irgendeinem „System“ beitreten, oder reicht der Poolvertrag mit unserem Dienstleister?$q$, $q$Einordnung: Die PPWR verlangt, dass Wirtschaftsakteure, die wiederverwendbare Verpackungen verwenden, einem Wiederverwendungssystem angehören, das die Anforderungen des Anhangs VI erfüllt (Art. 27 PPWR); Anhang VI unterscheidet offene und geschlossene Kreislaufsysteme mit Anforderungen an Governance, Rücknahme und Rekonditionierung. Ein professioneller Poolvertrag (z. B. Paletten-Pooling) IST typischerweise die Teilnahme an einem solchen System – entscheidend ist, dass der Systembetreiber die Anhang-VI-Anforderungen abdeckt und Sie das belegen können. Folge: Systemzugehörigkeit je Mehrweg-SKU dokumentieren (Vertrag + Systembeschreibung des Betreibers); das zahlt zugleich auf die Mehrweg-Einstufung (C06) und die deutsche § 11-Nr. 1-Ausnahme ein. Quellen: Art. 27 i. V. m. Anhang VI PPWR; § 11 Nr. 1 VerpackDG. Grenze: (!) Die genauen Absatz-Pins zu Art. 27/28 sind offen (V14 Anforderungspaket); die Subsumtion „Poolvertrag = Systemteilnahme“ ist Auslegung und in der Session zu bestätigen.$q$, 'mehrweg', array[$q$Art. 27 i. V. m. Anhang VI PPWR$q$,$q$§ 11 Nr. 1 VerpackDG$q$]::text[], 'unverbindliche_auslegung', '{30,3,27}'::int[], $q$! V14: Absatz-Pins Art. 27/28$q$, false),
(48, 'C08', $q$Ich habe ein kleines Café mit drei Aushilfen. Muss ich wirklich ein Mehrweg-Pfandsystem für Coffee-to-go anbieten?$q$, $q$Einordnung: Die Mehrwegangebotspflicht gilt weiter (Fortführung aus §§ 33/34 VerpackG): Endvertreiber, die Einwegkunststoff-Lebensmittelverpackungen oder Einweg-Getränkebecher erst vor Ort befüllen, müssen die Ware auch in wiederverwendbaren Verpackungen anbieten – nicht teurer und nicht zu schlechteren Bedingungen, einschließlich Deckel/Verschlüsse (§ 60 Abs. 1 VerpackDG), mit Hinweispflicht am POS und bei Lieferung (§ 60 Abs. 2). ABER für Sie greift die Kleinbetriebs-Erleichterung: Bei insgesamt höchstens fünf Beschäftigten und maximal 80 m² Verkaufsfläche genügt es, Kundengefäße zu befüllen (§ 61 Abs. 1) – Teilzeitkräfte zählen mit 0,5 (bis 20 Wochenstunden) bzw. 0,75 (bis 30 Wochenstunden); bei Lieferung zählen Lager-/Versandflächen zur Fläche. Auch dann: Hinweisschild auf das Befüll-Angebot (§ 61 Abs. 4) und Haftungsprivileg nur für Vorsatz/grobe Fahrlässigkeit (§ 61 Abs. 3). Quellen: §§ 60, 61 VerpackDG. Grenze: Zum 12.02.2028 wird § 60 auf „Einwegkunststoffgetränkebecher“ umgefasst (Mantelgesetz Art. 4) – der Radar meldet die Änderung (R10).$q$, 'mehrweg', array[$q$§ 60 VerpackDG$q$,$q$§ 61 VerpackDG$q$]::text[], 'rechtsverbindlich', '{29}'::int[], null, true),
(49, 'C09', $q$Muss auf jeder Verpackung jetzt unsere Adresse stehen? Und ist das dasselbe wie dieses neue EU-Sortierlabel?$q$, $q$Einordnung: Zwei verschiedene Regime. JETZT gilt die Identifikations- und Kontaktkennzeichnung: Auf ab dem 12.08.2026 in Verkehr gebrachten Verpackungen muss (a) eine Typen-, Chargen- oder Seriennummer oder ein anderes Identifikationselement und (b) Name oder eingetragene Marke, Postanschrift und eine digitale Kontaktmöglichkeit des Erzeugers angegeben sein – auf der Verpackung oder über einen Datenträger (z. B. QR-Code) abrufbar (Art. 15 Abs. 5 u. 6 PPWR); Importeure ergänzen ihre eigenen Angaben (Art. 18 Abs. 3). NOCH NICHT gilt das harmonisierte EU-Sortierlabel (Art. 12): Es kommt erst ab 12.08.2028 bzw. 24 Monate nach dem Durchführungsrechtsakt; bis dahin bleibt die deutsche Materialkennzeichnung nach § 4 VerpackDG freiwillig, aber exklusiv (nur die Nummern/Abkürzungen der Anlage 2). Folge: Druckdaten aller SKUs auf die Art.-15-Angaben prüfen; keine Investitionen in nationale Sortierhinweise mehr. Quellen: Art. 15 Abs. 5 u. 6, Art. 18 Abs. 3, Art. 12 PPWR; § 4 VerpackDG. Grenze: Detail-Pins zu Art. 15 (Mehrfachverpackungen, Verdeckungsverbot) sind V1-Positionen der Session.$q$, 'konformitaet', array[$q$Art. 15 Abs. 5 u. 6 PPWR$q$,$q$Art. 18 Abs. 3 PPWR$q$,$q$Art. 12 PPWR$q$,$q$§ 4 VerpackDG$q$]::text[], 'rechtsverbindlich', '{7,19}'::int[], $q$! V1: Detail-Pins Art. 15$q$, false),
(50, 'C10', $q$Für unsere PET-Einwegflaschen: Welche Rezyklatquote gilt denn nun – die deutsche oder die aus der EU-Verordnung?$q$, $q$Einordnung: Aktuell allein die deutsche. § 45 VerpackDG führt die nationale Quote fort: Einweggetränkeflaschen, die hauptsächlich aus PET bestehen, dürfen nur bereitgestellt werden, wenn sie zu mindestens 25 Masseprozent aus Kunststoffrezyklaten bestehen – wahlweise je Flasche oder im Jahresmittel des Herstellers mit nachprüfbarer Dokumentation gegenüber der Landesbehörde (§ 45 Abs. 1 u. 3). Ab dem 01.01.2030 gilt national 30 % für ALLE Einweggetränkeflaschen aus Kunststoff (§ 45 Abs. 2). Die EU-Rezyklatquoten des Art. 7 PPWR (je Kategorie, inkl. kontaktempfindlicher Verpackungen) greifen ebenfalls erst ab 2030 – dann laufen beide Regime parallel. Folge: Rezyklatanteil je Flaschen-SKU erfassen; bei Jahresmittel-Option den Dokumentationsprozess jetzt aufsetzen; Beschaffungsstrategie Richtung 2030 planen (Radar R4: Methodik-Rechtsakt). Quellen: § 45 Abs. 1–3 VerpackDG; Art. 7 PPWR. Grenze: (!) Das Konkurrenzverhältnis § 45 ↔ Art. 7 ab 2030 (strengster Wert? Anrechnung?) ist offene Session-Frage (V5); die EU-Prozentwerte je Kategorie sind als V4 gegen den Volltext zu pinnen – bis dahin nennen wir sie nicht.$q$, 'stoffrecht', array[$q$§ 45 Abs. 1–3 VerpackDG$q$,$q$Art. 7 PPWR$q$]::text[], 'rechtsverbindlich', '{15,14}'::int[], $q$! V4/V5: EU-Werte pinnen; Konkurrenz 2030 klären$q$, false)
on conflict (nr) do nothing;